function createPoller() {
  const buffer = new Array(100000).fill('data');
  const id = setInterval(() => {
    console.log('polling', buffer.length);
  }, 1000);
  return {
    stop() {
      clearInterval(id);
      console.log('stopped; the closure (and buffer) can now be collected');
    }
  };
}

const poller = createPoller();
poller.stop();

