const cache = [];

function addRow() {
  const row = document.createElement('div');
  document.body.appendChild(row);
  cache.push(row);
  return row;
}

function removeRow(row) {
  row.remove();
  const i = cache.indexOf(row);
  if (i !== -1) cache.splice(i, 1); // drop the JS reference too
}
// Now nothing reaches the detached node -> it is collectible.

function memoize(fn) {
  const cache = new WeakMap();
  return function (obj) {
    if (cache.has(obj)) return cache.get(obj);
    const result = fn(obj);
    cache.set(obj, result);
    return result;
  };
}

const compute = memoize((o) => o.value * 2);
let input = { value: 21 };
compute(input); // 42, cached
input = null;   // entry becomes collectible — no leak
